'use strict';

/**
 * planning-drift.cjs — store-mode cache drift detection (objective 48, D-15, GWP-03).
 *
 * In store mode the `.planning/` cache is gitignored, so git cannot see a direct write, and a pull rewrites files, so mtimes
 * prove nothing. Drift is decided by content instead: a cache or generated file whose current hash matches neither its
 * cache-index baseline (47: recorded after a completed pull or flush) nor its verb-write ledger entry (48-01: recorded by
 * the verb, pending its flush) was changed outside the aof-tools verbs. `validate health` reports each one as W055.
 *
 * Scope: `planning-paths.listByClass` files of class `cache` (minus `wiki/**`, whose truth is the wiki clone's git) and
 * `generated`. A generated view must also start with GENERATED_HEADER; one that does not was hand-edited.
 *
 * Local mode (planning-mode.cjs, D-01): `{applicable: false, drift: []}` and no outbox state is read at all.
 *
 * Read-only: the default index reader parses the 47 cache index itself instead of calling gh-outbox.readCacheIndex,
 * because that call quarantines (renames) a corrupt index and `validate health` must not move files. A corrupt index or
 * ledger throws, so the caller reports one "check failed" (W056) instead of flagging every file.
 *
 * Readers are injectable (`opts.readIndex` / `opts.readLedger`, then the `_setDriftReaders` seam, then the defaults).
 * No gh, no git, nothing spawned.
 */

const fs = require('fs');
const path = require('path');

const ghTrd = require('./gh-trd.cjs');
const planningMode = require('./planning-mode.cjs');
const planningPaths = require('./planning-paths.cjs');

/** gh-cache.cjs GENERATED_HEADER, copied so this module does not load the gh client stack; a test asserts they agree. */
const GENERATED_HEADER = '<!-- generated by aoforge; do not edit -->';

/** Hash at most this many files per run; beyond it the result carries a note. */
const MAX_FILES = 5000;

/** gh-outbox's per-repo suffix for the cache index (`writeCacheIndex` / `readCacheIndex`). */
const CACHE_INDEX_SUFFIX = '.cache.json';

const REASONS = Object.freeze(['no-baseline', 'changed', 'hand-edited']);

function isPlainObject(v) {
  return v !== null && typeof v === 'object' && !Array.isArray(v);
}

// ─── default readers ─────────────────────────────────────────────────────────

/**
 * The 47 cache index `{rel: hash}` for `root`, `{}` when there is none. Same file and shape check as
 * gh-outbox.readCacheIndex, but never quarantines: an unreadable index throws and stays byte-identical.
 */
function defaultReadIndex(root, opts = {}) {
  const outbox = require('./gh-outbox.cjs');
  const file = path.join(outbox.stateDir(opts.env || process.env, opts.home), `${outbox.repoKey(root)}${CACHE_INDEX_SUFFIX}`);
  let raw;
  try {
    raw = fs.readFileSync(file, 'utf8');
  } catch (e) {
    if (e && e.code === 'ENOENT') return {};
    throw e;
  }
  let parsed;
  try {
    parsed = JSON.parse(raw);
  } catch {
    parsed = undefined;
  }
  if (!isPlainObject(parsed) || !Object.values(parsed).every((v) => typeof v === 'string')) {
    throw new Error(`cache index ${file} is unreadable; \`aof-tools gh pull --all\` rebuilds it`);
  }
  return parsed;
}

/** planning-ledger.readLedger: `{version, entries, corrupt}`, never writes. */
function defaultReadLedger(root, opts = {}) {
  return require('./planning-ledger.cjs').readLedger(root, opts);
}

let injected = null;

/**
 * Test seam: install module-level readers (`{readIndex?, readLedger?}`) used when `opts` names none. `null` restores the
 * defaults. validate.cjs calls `findCacheDrift(cwd)` without readers, so its tests inject through here.
 */
function _setDriftReaders(readers) {
  injected = readers && typeof readers === 'object' ? { ...readers } : null;
}

function pickReader(opts, name, fallback) {
  if (typeof opts[name] === 'function') return opts[name];
  if (injected && typeof injected[name] === 'function') return injected[name];
  return fallback;
}

// ─── messages ────────────────────────────────────────────────────────────────

/** The W055 text for one drifted file (D-15). Also its `fix`. */
function driftMessage({ rel, cls, verb, reason }) {
  const head = `${rel} was changed outside an aof-tools verb (${reason}); `;
  if (cls === 'generated') {
    const tail = 'regenerate with `aof-tools gh pull --all`';
    // gh-cache never overwrites a generated file that lacks the header (hand_maintained, not even with --force).
    return reason === 'hand-edited' ? `${head}${tail} (pull skips a file without the generated header: move it aside first)` : `${head}${tail}`;
  }
  return `${head}use \`aof-tools ${verb}\` to publish it, or \`aof-tools gh pull --all --force\` to restore GitHub's version`;
}

// ─── the check ───────────────────────────────────────────────────────────────

/** Sorted rels to check: cache (minus wiki/**) and generated. */
function candidates(planningDir) {
  const byClass = planningPaths.listByClass(planningDir);
  const cache = byClass.cache.filter((rel) => !rel.startsWith('wiki/'));
  return [...cache, ...byClass.generated].sort();
}

function validIndex(index) {
  return isPlainObject(index) && Object.values(index).every((v) => typeof v === 'string');
}

/** `{rel: hash}` from a ledger read; throws for a corrupt or malformed one. */
function ledgerHashes(ledger) {
  if (!isPlainObject(ledger) || !isPlainObject(ledger.entries)) {
    throw new TypeError('verb-write ledger reader returned no {entries} object');
  }
  if (ledger.corrupt === true) {
    throw new Error('verb-write ledger is unreadable (corrupt); pending verb writes cannot be told from direct edits');
  }
  const out = {};
  for (const [rel, entry] of Object.entries(ledger.entries)) {
    if (isPlainObject(entry) && typeof entry.hash === 'string') out[rel] = entry.hash;
  }
  return out;
}

/** The file's text, or null when it vanished since the listing. Other read errors propagate. */
function readText(abs) {
  try {
    return fs.readFileSync(abs, 'utf8');
  } catch (e) {
    if (e && e.code === 'ENOENT') return null;
    throw e;
  }
}

/**
 * findCacheDrift(root, opts) -> `{applicable, root, drift, checked, notes}`.
 *
 * - `applicable` false (local mode): `drift: []`, no reader is called.
 * - `drift`: `[{rel, class, verb, reason, message, fix, hint}]` sorted by rel; `reason` is `no-baseline` (no baseline,
 *   no ledger entry), `changed` (bytes match neither) or `hand-edited` (a generated view without GENERATED_HEADER).
 * - `checked`: files hashed; `notes`: why the check was partial (the MAX_FILES cap).
 *
 * Throws when a reader throws or returns a malformed or corrupt store; the caller reports that as W056.
 *
 * @param {string} root any cwd in the project; the MAIN checkout is resolved first (D-14)
 * @param {{readIndex?: Function, readLedger?: Function, home?: string, env?: object, maxFiles?: number}} [opts]
 */
function findCacheDrift(root, opts = {}) {
  const pm = planningMode.planningMode(root);
  if (pm.mode !== planningMode.STORE) return { applicable: false, root: pm.root, drift: [], checked: 0, notes: [] };

  const mainRoot = pm.root;
  const readerOpts = {};
  if (opts.home !== undefined) readerOpts.home = opts.home;
  if (opts.env !== undefined) readerOpts.env = opts.env;

  const index = pickReader(opts, 'readIndex', defaultReadIndex)(mainRoot, readerOpts);
  if (!validIndex(index)) throw new TypeError('cache index reader returned something other than {rel: hash}');
  const ledger = ledgerHashes(pickReader(opts, 'readLedger', defaultReadLedger)(mainRoot, readerOpts));

  const maxFiles = Number.isInteger(opts.maxFiles) && opts.maxFiles > 0 ? opts.maxFiles : MAX_FILES;
  const planningDir = path.join(mainRoot, '.planning');
  const all = candidates(planningDir);
  const notes = [];
  if (all.length > maxFiles) {
    notes.push(`checked the first ${maxFiles} of ${all.length} cache files; the other ${all.length - maxFiles} were not checked`);
  }

  const drift = [];
  let checked = 0;
  for (const rel of all.slice(0, maxFiles)) {
    const text = readText(path.join(planningDir, ...rel.split('/')));
    if (text === null) continue;
    checked++;

    const c = planningPaths.classify(rel);
    const h = ghTrd.contentHash(text);
    const hasIndex = Object.hasOwn(index, rel);
    const hasLedger = Object.hasOwn(ledger, rel);

    let reason = null;
    if (c.class === 'generated' && !text.startsWith(GENERATED_HEADER)) reason = 'hand-edited';
    else if (hasIndex && index[rel] === h) reason = null;
    else if (hasLedger && ledger[rel] === h) reason = null;
    else reason = hasIndex || hasLedger ? 'changed' : 'no-baseline';
    if (!reason) continue;

    const message = driftMessage({ rel, cls: c.class, verb: c.verb, reason });
    drift.push({ rel, class: c.class, verb: c.verb, reason, message, fix: message, hint: c.hint });
  }

  return { applicable: true, root: mainRoot, drift, checked, notes };
}

module.exports = {
  GENERATED_HEADER,
  MAX_FILES,
  REASONS,
  findCacheDrift,
  driftMessage,
  defaultReadIndex,
  _setDriftReaders,
};
